import React, { forwardRef } from 'react';

import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Flex } from '../../layouts-core/flex/Flex.js';

export interface MenuItemIconProps extends WithChildren, AriaLabelingProps {}

/**
 * An icon which can be used as a child of an Item.
 */
export const ItemIcon = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  MenuItemIconProps
>(
  (
    {
      children,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledBy,
      'aria-describedby': ariaDescribedBy,
      'aria-details': ariaDetails,
    },
    forwardedRef,
  ) => {
    return (
      <Flex
        ref={forwardedRef}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledBy}
        aria-describedby={ariaDescribedBy}
        aria-details={ariaDetails}
      >
        {children}
      </Flex>
    );
  },
);

(ItemIcon as typeof ItemIcon & { displayName: string }).displayName =
  'Menu.ItemIcon';
